def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    return np.where(rem >= 0, 1.0 / (rem + 1e-5), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    target = 0.5
    return np.where(rem >= 0, -np.abs(rem - target), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    return np.where(rem >= 0, rem, -np.inf)
